Dalam prosedur Mystery berikut ini, angka parameternya adalah bilangan bulat positif.

 PROCEDURE Mystery (number)
 {
 REPEAT UNTIL (number <= 0)
 {
  number ← number - 2
 }
 IF (number = 0)
 {
  RETURN (true)
 }
 ELSE
 {
  RETURN (false)
 }
 }

