Prosedur di bawah ini dimaksudkan untuk menampilkan indeks dalam daftar nama unik (nameList), di mana nama tertentu (targetName) ditemukan. Jika targetName tidak ditemukan dalam nameList, kode harus menampilkan 0.
 PROCEDURE FindName (nameList, targetName)
 {
 index ← 0
 FOR EACH name IN nameList
 {
  index ← index + 1
  IF (name = targetName)
  {
  foundIndex ← index
  }
  ELSE
  {
  foundIndex ← 0
  }
 }
 DISPLAY (foundIndex)
 }
